//! RankCLI WASM Audit Engine
//!
//! The 280+ SEO checks are compiled to JS, encrypted, and embedded in this binary.
//! Users install `rankcli` and get the WASM - they never see the source code.
//!
//! Architecture:
//! 1. WASM contains encrypted JS code (AES-256-GCM)
//! 2. License key derives decryption key
//! 3. Decrypted code is passed to Node.js VM for execution
//! 4. WASM controls tier limits and validation

use wasm_bindgen::prelude::*;
use serde::{Deserialize, Serialize};
use std::sync::OnceLock;

mod decrypt;

// Embedded encrypted checks (generated by build.rs)
include!(concat!(env!("OUT_DIR"), "/embedded_checks.rs"));

// Global state
static DECRYPTED_CODE: OnceLock<String> = OnceLock::new();
static CURRENT_TIER: OnceLock<String> = OnceLock::new();

#[derive(Serialize, Deserialize)]
pub struct AuditResult {
    pub success: bool,
    pub score: u32,
    pub issues: Vec<AuditIssue>,
    #[serde(rename = "checksRun")]
    pub checks_run: u32,
    pub tier: String,
}

#[derive(Serialize, Deserialize)]
pub struct AuditIssue {
    pub code: String,
    pub severity: String,
    pub category: String,
    pub title: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub impact: Option<String>,
    #[serde(rename = "howToFix", skip_serializing_if = "Option::is_none")]
    pub how_to_fix: Option<String>,
}

/// Initialize the engine with the build-time decrypt passphrase.
/// Decrypts the embedded checks and stores them for execution.
///
/// The `license_key` parameter is misleadingly named for what it does
/// now: entitlement (is this user actually paid?) is decided in
/// TypeScript, from the real Supabase-backed apiKey/plan the CLI already
/// validates on login - not by anything checkable here. The caller only
/// invokes this at all once it has confirmed a paid apiKey, always
/// passing the single build-embedded passphrase (see
/// scripts/inject-config.js), never a user-supplied string. This
/// decryption step exists purely to keep the premium check source out of
/// static analysis of the shipped binary; get_tier()/get_checks_limit()/
/// validate_license() below are legacy from an earlier signed-license
/// design that was never finished and should not be trusted as an
/// entitlement source.
#[wasm_bindgen]
pub fn init_engine(license_key: &str) -> Result<bool, JsError> {
    if DECRYPTED_CODE.get().is_some() {
        return Ok(true); // Already initialized
    }

    // Derive decryption key from license
    let key = decrypt::derive_key(license_key);

    // Decrypt the embedded JS checks
    let js_code = decrypt::decrypt_checks(&key, ENCRYPTED_CHECKS, ENCRYPTION_NONCE)
        .map_err(|e| JsError::new(&format!("Invalid license key: {}", e)))?;

    // Store decrypted code
    DECRYPTED_CODE
        .set(js_code)
        .map_err(|_| JsError::new("Engine already initialized"))?;

    // Determine and store tier
    let tier = validate_license_internal(license_key);
    let _ = CURRENT_TIER.set(tier);

    Ok(true)
}

/// Get the decrypted JavaScript code for execution.
/// This is called by the Node.js wrapper which runs it in a VM sandbox.
/// The code is ONLY available after successful init_engine() with valid license.
#[wasm_bindgen]
pub fn get_decrypted_code() -> Result<String, JsError> {
    DECRYPTED_CODE
        .get()
        .cloned()
        .ok_or_else(|| JsError::new("Engine not initialized. Call init_engine() first."))
}

/// Validate a license key and return the tier
#[wasm_bindgen]
pub fn validate_license(license_key: &str) -> String {
    validate_license_internal(license_key)
}

fn validate_license_internal(license_key: &str) -> String {
    // Production implementation would:
    // 1. Base64 decode the license
    // 2. Verify Ed25519 signature against embedded public key
    // 3. Parse JSON payload for tier and expiration
    // 4. Check expiration date

    // Current: prefix-based detection for development
    if license_key.starts_with("agency_") || license_key.contains("AGENCY") {
        "agency".to_string()
    } else if license_key.starts_with("pro_") || license_key.contains("PRO") {
        "pro".to_string()
    } else if license_key.starts_with("solo_") || license_key.contains("SOLO") {
        "solo".to_string()
    } else if !license_key.is_empty() {
        "registered".to_string()
    } else {
        "free".to_string()
    }
}

/// Get checks limit for current tier
#[wasm_bindgen]
pub fn get_checks_limit() -> u32 {
    match CURRENT_TIER.get().map(|s| s.as_str()) {
        Some("agency") | Some("pro") | Some("solo") => 280,
        Some("registered") => 100,
        _ => 50,
    }
}

/// Get current tier
#[wasm_bindgen]
pub fn get_tier() -> String {
    CURRENT_TIER
        .get()
        .cloned()
        .unwrap_or_else(|| "free".to_string())
}

/// Get version info
#[wasm_bindgen]
pub fn version() -> String {
    format!(
        "RankCLI v{} (WASM engine, {} bytes embedded)",
        env!("CARGO_PKG_VERSION"),
        ENCRYPTED_CHECKS.len()
    )
}

/// Check if engine is initialized
#[wasm_bindgen]
pub fn is_initialized() -> bool {
    DECRYPTED_CODE.get().is_some()
}

/// Get size of encrypted payload (for debugging)
#[wasm_bindgen]
pub fn get_encrypted_size() -> usize {
    ENCRYPTED_CHECKS.len()
}
